const evaluations = [
  {reg:'25ME001',name:'Bharath R',application:'Automotive engine crankshaft under cyclic bending and torsion',scores:[3,4,2,8,7,1,2],good:'You selected forged, heat-treated AISI 4340, a defensible crankshaft material, and recognized fatigue, strength and toughness as relevant.',improve:'The report is only a conclusion. Define torque, bending, speed, temperature and life; compare 4340 with at least two realistic candidates using verified numerical properties. Replace “correct” and the one-line reflection with claim-by-claim checking and your own engineering judgement.'},
  {reg:'25ME002',name:'Darwin Cyril S',application:'Automotive suspension coil spring with high fatigue resistance',scores:[7,11,7,12,9,2,4],good:'You connected SAE 9254 to cyclic loading and correctly identified heat treatment, shot peening, surface defects and corrosion protection as important to spring life.',improve:'The prompt asked for alternatives, but the report does not actually compare SAE 9254, 5160 and stainless spring steel using a consistent decision method. Verify the assumed Indian price and spring mass, and describe one specific AI error or correction instead of a generic warning.'},
  {reg:'25ME003',name:'Devendhiran S',application:'Railway wheel under rolling contact and impact loading',scores:[2,2,0,1,5,2,1],good:'You identified relevant criteria and located an Indian Railways/RDSO wheel specification, which is an appropriate authoritative source.',improve:'The submitted “report” repeats the task and never selects or evaluates a material. Name the applicable wheel-steel grade, quantify hardness/strength/toughness requirements, compare candidates, cite the exact standard clauses used, and document what the AI output got wrong or omitted.'},
  {reg:'25ME005',name:'Gurusaran R',application:'Hot-forging die under impact, wear and elevated temperature',scores:[7,10,7,12,11,8,4],good:'You gave a well-focused H13 justification and uniquely linked hot hardness, impact toughness, wear and thermal-fatigue resistance to alloying and heat checking. Your corrections are specific and supported by reputable tool-steel producers.',improve:'Add actual die temperature, contact pressure and thermal-cycle conditions. Compare H13 quantitatively with H11 and a higher-wear option, then use a weighted matrix or explicit trade-off. Include target heat treatment/hardness and fully traceable citations without AI-added tracking parameters.'},
  {reg:'25ME006',name:'Harish Maruthu R',application:'Automobile engine block with damping, castability and wear resistance',scores:[5,8,4,10,6,1,3],good:'You correctly connected graphite flakes in pearlitic grey cast iron with damping, machinability and useful cylinder-bore wear behaviour.',improve:'Specify engine type, cylinder pressure and temperature, and compare grey iron with compacted-graphite iron and an aluminium-silicon alloy. Provide grade/property data and precise references. “Correct” and “Good” do not demonstrate verification or personal learning.'},
  {reg:'25ME008',name:'Idris A',application:'Lightweight commercial-aircraft fuselage skin',scores:[2,3,1,5,3,1,1],good:'You identified 2024 aluminium as a plausible high-strength, low-density aircraft alloy and attempted to use a NASA source.',improve:'One sentence is not a material-selection report. Define fatigue, damage tolerance, corrosion, joining and skin-gauge requirements; compare 2024-T3 with 2524/2024 variants, 7075 and composites. Give traceable source details and independently check temper, corrosion protection and application limitations.'},
  {reg:'25ME010',name:'Koushik N',application:'Electric-vehicle battery enclosure for low weight, crash resistance and heat dissipation',scores:[9,13,15,13,3,2,5],good:'The report is technically well organized, compares several candidates, and recognizes that crash and thermal performance depend on geometry, joints, coatings and the cooling architecture—not alloy designation alone.',improve:'The submitted source is only the ASM homepage, so the numerical properties and design claims are not auditable. Cite specific datasheets, papers and battery/crash standards beside claims. Your correction and reflection must identify concrete checks you personally performed; otherwise the polished AI report is not evidence of critical AI use.'},
  {reg:'25ME011',name:'Maheswaran A',application:'Lightweight bicycle frame with strength, corrosion resistance and manufacturability',scores:[8,12,15,13,8,3,5],good:'You compared five material families, selected 6061-T6 for a clearly stated production context, and correctly noted aluminium’s lack of a true endurance limit and the importance of weld-joint quality.',improve:'Turn the qualitative comparison into a transparent decision matrix with tube-level stiffness/fatigue constraints. Give exact, retrievable source links or document identifiers. “Correct” is not sufficient verification—check temper loss in welded zones and explain any resulting design or post-weld heat-treatment decision.'},
  {reg:'25ME013',name:'Manivel S',application:'High-current connector needing conductivity, strength and thermal performance',scores:[6,9,7,9,8,2,4],good:'You distinguished high-strength and high-conductivity beryllium-copper families and recognized the conductivity–spring-strength trade-off and beryllium manufacturing hazard.',improve:'Choose a specific alloy/temper and compare it with pure copper, CuCrZr and brass using conductivity (%IACS), contact resistance, stress relaxation and temperature limits. Thermal resistance is a component geometry value, not simply a material property. Verification must check the exact grade rather than conclude only that copper conducts.'},
  {reg:'25ME014',name:'Mathubalan T',application:'Lightweight delivery-drone structural frame',scores:[4,6,3,8,0,2,3],good:'You correctly connected CFRP’s specific stiffness and low mass with payload, battery demand and flight time, and noted cost/manufacturing disadvantages.',improve:'No genuine verification sources were supplied; the source and correction fields contain form-writing advice from the AI. Define payload, arm span, vibration and crash/landing loads, compare CFRP with aluminium and GFRP, address lay-up/joints/damage, and cite actual datasheets or studies.'},
  {reg:'25ME015',name:'Menaka S',application:'Lightweight automobile gearbox housing with castability and vibration control',scores:[7,11,7,11,9,4,4],good:'You chose a castable A356 Al–Si alloy, linked requirements to suitable tests, and included casting-defect inspection as well as mechanical and vibration testing.',improve:'Compare A356 quantitatively with grey iron, magnesium and another aluminium casting alloy. “Good vibration damping” needs numerical support and comparison because aluminium generally damps less than cast iron. State casting route and temper, and explain a specific AI claim that you corrected.'},
  {reg:'25ME016',name:'Nasilan N',application:'Biocompatible load-bearing hip implant stem',scores:[9,13,15,13,12,2,5],good:'The report gives a strong service-condition analysis, compares Ti-6Al-4V with Co–Cr, 316L and ceramics, and correctly discusses fatigue, stress shielding, passive-film corrosion and surface engineering. The FDA example and biomedical reviews are relevant.',improve:'The reflection says the answer was verified “with AI,” which is not independent verification. Tie individual property and biocompatibility claims to ASTM F136/ISO implant requirements, distinguish Ti-6Al-4V ELI from general Ti-6Al-4V, and record one limitation or correction discovered through the cited sources.'},
  {reg:'25ME017',name:'Navin P',application:'Aircraft compressor blade with high specific strength and fatigue resistance',scores:[6,9,5,11,10,1,4],good:'You selected Ti-6Al-4V for low/intermediate compressor temperatures and listed appropriate fatigue, fracture, creep, corrosion and nondestructive tests. The references are relevant to compressor-blade fatigue.',improve:'Define compressor stage temperature, rotational stress and foreign-object-damage conditions, then compare titanium with stainless steel and nickel alloy options. Use quantitative specific strength and fatigue data. “Correct” and “How to use AI” do not show any independent checking or reflection.'},
  {reg:'25ME020',name:'Pratheesh Kumar B',application:'Lightweight satellite structural panel with dimensional stability',scores:[9,14,16,13,12,2,5],good:'You developed an unusually complete CFRP–honeycomb concept, linked fibre orientation to stiffness/CTE, discussed thermal cycling, outgassing, moisture, radiation and galvanic coupling, and used strong NASA/ESA/ASTM source types.',improve:'Your correction and reflection do not demonstrate ownership of the sophisticated report. Show a numerical thermal-expansion comparison, give a weighted selection table, identify exact CFRP laminate/core data, and state which AI claim you checked, rejected or changed using the cited standards.'},
  {reg:'25ME021',name:'Sanjai L',application:'High-speed robotic arm with high stiffness and low inertia',scores:[7,11,12,12,10,4,4],good:'You correctly focused on specific stiffness and moving inertia, compared four candidate families, and connected CFRP mass reduction to acceleration, positioning and motor demand. A robot-arm-specific journal source strengthens the choice.',improve:'Quantify link length, payload, deflection, natural frequency and acceleration. Compare candidates using E/ρ and a bending-stiffness model rather than “high/low” labels, and address anisotropy, joint inserts and damage inspection. Document a specific verified correction, not only general comments about AI.'},
  {reg:'25ME023',name:'Santhosh R',application:'Chemical-storage tank with corrosion resistance and economical fabrication',scores:[6,8,5,9,10,7,4],good:'You explicitly rejected universal suitability of SS304 and stated that chemical identity, concentration and temperature control the decision. That is a valuable correction to a common AI overgeneralization.',improve:'A storage-tank material cannot be selected before the stored chemical and service conditions are defined. Make the recommendation conditional, use compatibility/corrosion-rate data, and compare 304L, 316L, duplex steel and polymer/FRP options with fabrication and life-cycle cost. ASTM A240 is a product specification, not proof of chemical compatibility.'},
  {reg:'25ME024',name:'Santhosh S',application:'Pump mechanical seal for abrasive and corrosive fluids',scores:[8,13,10,12,10,8,5],good:'You distinguished sintered SiC from reaction-bonded SiC and connected free silicon, hardness, conductivity and thermal expansion to abrasion, corrosion and seal-face stability. The correction is specific and technically relevant.',improve:'Define the actual fluid chemistry, solids size/loading, pressure, speed and dry-run risk. Compare SSiC with tungsten carbide and carbon/SiC using a decision table. Avoid blanket “entire pH 0–14” claims without grade-, temperature- and fluid-specific compatibility data, and give exact datasheet editions/pages.'},
  {reg:'25ME026',name:'Sribhuvan B',application:'High-speed bearing balls in a machine-tool spindle',scores:[9,14,16,11,0,0,4],good:'The technical section identifies the correct hybrid-bearing concept and meaningfully discusses dN, centrifugal loading, gyroscopic skidding, thermal expansion, stiffness and candidate trade-offs.',improve:'The source, correction and reflection fields largely duplicate the AI report instead of providing sources or personal analysis, so they receive no credit. Verify claims such as the 30–50% preload reduction and “increased stiffness” against bearing-manufacturer data/standards, correct overstatements about steel, and write a genuine reflection in your own words.'},
  {reg:'25ME028',name:'Vimalraj D',application:'Cutting tool for high-speed machining of nickel superalloys',scores:[6,8,4,10,6,1,4],good:'You correctly identified why nickel superalloys are difficult to machine and selected SiAlON for hot hardness, wear resistance and thermal stability at high cutting speed.',improve:'Compare SiAlON with whisker-reinforced alumina, coated carbide, CBN and possibly ceramic grades under specified speed/feed/coolant conditions. Add quantitative tool-life or wear data and traceable citations. “Fast answer” and “AI is perfect” are not verification; identify limitations such as interrupted-cut sensitivity and notch wear.'},
  {reg:'25ME029',name:'Vishal Kiptson S',application:'Aircraft bearing cage with low weight, wear resistance and temperature stability',scores:[7,10,5,11,0,0,4],good:'You correctly explained the cage function and connected PEEK’s density, tribology, temperature capability, chemical resistance and dimensional stability to aerospace bearing service.',improve:'The “sources” field repeats the report and the correction/reflection fields contain AI requests for more information; none demonstrate your work. Compare neat PEEK with reinforced/bearing-grade PEEK, polyamide-imide and metallic cages, define temperature/speed/lubricant, and verify properties with aerospace-grade datasheets and bearing literature.'},
  {reg:'25ME030',name:'Yogeshwara S',application:'Transparent industrial safety visor with impact resistance',scores:[9,13,16,10,4,9,5],good:'You made a strong toughness-versus-hardness distinction, compared transparent candidates, considered coatings and secondary hazards, and wrote a specific reflection explaining why energy absorption matters more than static strength.',improve:'Several impressive-looking values and standards need direct citations. Verify the exact ANSI/EN impact class, specimen geometry and velocity; remove questionable overclaims such as ALON being four times harder than sapphire; and separate visor-lens selection from unnecessary frame-alloy discussion. Provide authoritative standards/datasheets in the sources field.'},
  {reg:'25ME031',name:'Vishal V',application:'Automotive air-intake manifold exposed to heat, vibration and oil vapours',scores:[5,8,5,9,3,1,3],good:'You selected a plausible glass-fibre-reinforced polyamide and recognized injection moulding, dimensional stability, weight and the possible need for a higher-temperature grade.',improve:'Define continuous/peak temperature, humidity, boost pressure and fluid exposure; PA6 moisture uptake is a key omission. Compare PA6-GF30 with PA66-GF30, PPS-GF and aluminium using verified grade data. The price and suitability claims are not properly sourced, and verification “with AI” is not independent.'},
  {reg:'26LME01',name:'Siva Prasath M',application:'Chemical-processing valve seat with low friction and chemical resistance',scores:[7,11,6,11,9,6,4],good:'You correctly linked PTFE to friction, sealing and chemical resistance, and importantly noted creep/strength limitations plus the need for chemical, wear, leakage and pressure–temperature tests.',improve:'Specify chemical, concentration, temperature, pressure and valve type before final selection. Compare virgin PTFE with filled PTFE, PEEK and appropriate elastomers, using creep, wear and pressure–temperature limits. Supply exact Chemours/MatWeb document details and clarify when “good wear resistance” is not true for unfilled PTFE.'},
  {reg:'26LME02',name:'Suthesh M',application:'Lead-acid battery casing with chemical and impact resistance',scores:[8,12,6,12,11,3,4],good:'You gave a thorough connection between impact-modified PP, sulfuric-acid containment, vibration, electrical insulation and injection-moulded case features. The battery-housing standard and battery-case research are relevant.',improve:'The report is long but lacks candidate comparison and a transparent selection method. Compare impact-modified PP with earlier hard-rubber/other polymer options and specify temperature, impact and acid-test criteria. State exactly which AI claim was wrong and how the cited source changed it; the current correction and reflection are too vague.'},
  {reg:'26LME03',name:'Vignesh S',application:'Underground drinking-water pipeline with corrosion resistance and flexibility',scores:[9,14,7,13,11,6,5],good:'You provided a strong service-condition analysis covering soil, surge, pressure class, temperature, potable-water approval, disinfectants, fusion quality, bedding and contamination/permeation. The recommendation is sensibly conditional on standards and installation.',improve:'PE4710 is a North-American designation while PE100/IS 4984 may be more relevant locally; reconcile the chosen grade and jurisdiction. Compare HDPE quantitatively with PVC, ductile iron and steel, include pressure/SDR design and life-cycle cost, and identify the exact claims you personally corrected rather than using a generic correction statement.'}
];

const criteria = [
  ['Definition of application and service conditions',10],
  ['Identification of material requirements',15],
  ['Candidate comparison and selection method',20],
  ['Technical accuracy',15],
  ['Verification and quality of sources',15],
  ['Critical use of AI and reflection',10],
  ['Report clarity and organization',5]
];

const list = document.querySelector('#studentList');
const search = document.querySelector('#studentSearch');
const empty = document.querySelector('#emptyState');
const panel = document.querySelector('#resultPanel');

function totalOf(item){ return item.scores.reduce((a,b)=>a+b,0); }
function escapeText(value){ const d=document.createElement('div'); d.textContent=value; return d.innerHTML; }

function renderList(filter=''){
  const q=filter.trim().toLowerCase();
  const matches=evaluations.filter(x=>`${x.name} ${x.reg}`.toLowerCase().includes(q));
  list.innerHTML=matches.map(x=>`<button class="student-button" data-reg="${x.reg}"><span>${escapeText(x.name)}</span><small>${x.reg}</small></button>`).join('');
  document.querySelector('#noMatch').hidden=matches.length!==0;
}

function showResult(reg, updateHash=true){
  const item=evaluations.find(x=>x.reg===reg);
  if(!item) return;
  const total=totalOf(item);
  empty.hidden=true;
  panel.hidden=false;
  panel.innerHTML=`
    <div class="result-head">
      <div><p class="section-number">INDIVIDUAL FEEDBACK</p><h2>${escapeText(item.name)}</h2><p>${item.reg} · ${escapeText(item.application)}</p></div>
      <div class="score-badge"><strong>${total}</strong><span>/ 90 provisional</span></div>
    </div>
    <div class="oral-pending"><strong>Presentation and oral defence: pending (10 marks)</strong><span>Final score out of 100 will be issued only after the oral defence.</span></div>
    <div class="rubric-table-wrap"><table><thead><tr><th>Criterion</th><th>Mark</th><th>Maximum</th></tr></thead><tbody>
      ${criteria.map((c,i)=>`<tr><td>${c[0]}</td><td><strong>${item.scores[i]}</strong></td><td>${c[1]}</td></tr>`).join('')}
      <tr class="total-row"><td>Written submission total</td><td><strong>${total}</strong></td><td>90</td></tr>
    </tbody></table></div>
    <div class="feedback-grid">
      <article class="feedback-card positive"><h3>What you did well and uniquely</h3><p>${escapeText(item.good)}</p></article>
      <article class="feedback-card improve"><h3>What to improve</h3><p>${escapeText(item.improve)}</p></article>
    </div>
    <p class="review-note">This is a rubric-based provisional evaluation of the latest submitted version. The oral-defence mark is intentionally not estimated from the written report.</p>`;
  document.querySelectorAll('.student-button').forEach(b=>b.classList.toggle('active',b.dataset.reg===reg));
  if(updateHash) history.replaceState(null,'',`#${reg}`);
  panel.scrollIntoView({behavior:'smooth',block:'start'});
}

list.addEventListener('click',e=>{ const b=e.target.closest('.student-button'); if(b) showResult(b.dataset.reg); });
search.addEventListener('input',()=>renderList(search.value));
renderList();
const initial=location.hash.slice(1).toUpperCase();
if(evaluations.some(x=>x.reg===initial)) showResult(initial,false);
